3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns a newly built owner its {@code membershipNumber}, formatted
8	 * {@code <customerCode>-M<YY>}, where YY is the last two digits of the registration
9	 * date year (e.g. {@code NSW-1A2B3C4D-M26}). Runs after both the customer code and the
10	 * registration date have been assigned, so both inputs are present.
11	 */
12	public class AssignMembershipNumber {
13	
14	    public void service(@Val Owner owner) {
15	        int yy = owner.getRegistrationDate().getYear() % 100;
16	        owner.setMembershipNumber(String.format("%s-M%02d", owner.getCustomerCode(), yy));
17	    }
18	}
