1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Out;
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * Resolves the effective registration date for a create-owner request and publishes it for
11	 * later steps: the request's date when supplied, otherwise the server's current date, in
12	 * either case rolled forward to a business day (see {@link BusinessDay}). Runs before the
13	 * daily-limit guard so the cap counts per adjusted business day, and before the date is
14	 * applied to the owner so the membership number's year segment uses the adjusted value.
15	 */
16	public class ResolveRegistrationDate {
17	
18	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
19	        LocalDate supplied = request.getRegistrationDate();
20	        LocalDate effective = (supplied != null) ? supplied : LocalDate.now();
21	        registrationDate.set(BusinessDay.rollForward(effective));
22	    }
23	}
